import java.util.Map;
import org.junit.Assert;
import org.junit.Rule;
import org.junit.Test;

/** Unit test for {@link HelloSearchAttributes}. Doesn't use an external Temporal service. */
public class HelloSearchAttributesTest {

  @Rule
  public TestWorkflowRule testWorkflowRule =
      TestWorkflowRule.newBuilder()
          .setWorkflowTypes(HelloSearchAttributes.GreetingWorkflowImpl.class)
          .setDoNotStart(true)
          .build();

  @Test
  public void testStartWorkflowWithSearchAttribute() {

    final String taskQueue = testWorkflowRule.getTaskQueue();
    final String workflowId = "workflowId";
    final String customKeywordField = "CustomKeywordField";
    final String customKeywordValue = "CustomKeywordValue";

    testWorkflowRule
        .getWorker()
        .registerActivitiesImplementations(new HelloSearchAttributes.GreetingActivitiesImpl());
    testWorkflowRule.getTestEnvironment().start();

    // Get a workflow stub using the same task queue the worker uses.
    final HelloSearchAttributes.GreetingWorkflow workflow =
        testWorkflowRule
            .getWorkflowClient()
            .newWorkflowStub(
                HelloSearchAttributes.GreetingWorkflow.class,
                WorkflowOptions.newBuilder()
                    .setSearchAttributes(Map.of(customKeywordField, customKeywordValue))
                    .setWorkflowId(workflowId)
                    .setTaskQueue(taskQueue)
                    .build());

    final WorkflowStub untyped = WorkflowStub.fromTyped(workflow);
    final WorkflowExecution execution = untyped.start("Hello");

    // wait until workflow completes
    untyped.getResult(String.class);

    final DescribeWorkflowExecutionResponse resp =
        testWorkflowRule
            .getWorkflowClient()
            .getWorkflowServiceStubs()
            .blockingStub()
            .describeWorkflowExecution(
                DescribeWorkflowExecutionRequest.newBuilder()
                    .setNamespace(testWorkflowRule.getTestEnvironment().getNamespace())
                    .setExecution(execution)
                    .build());
    // get all search attributes
    final SearchAttributes searchAttributes = resp.getWorkflowExecutionInfo().getSearchAttributes();

    Assert.assertEquals(
        customKeywordValue, getKeywordFromSearchAttribute(searchAttributes, customKeywordField));
  }
}

package io.temporal.samples.tracing;

import static org.junit.Assert.*;

import io.jaegertracing.internal.JaegerSpan;
import io.jaegertracing.internal.JaegerTracer;
import io.jaegertracing.internal.reporters.InMemoryReporter;
import io.jaegertracing.internal.samplers.ConstSampler;
import io.jaegertracing.spi.Sampler;
import io.opentracing.Tracer;
import io.temporal.client.WorkflowClient;
import io.temporal.client.WorkflowClientOptions;
import io.temporal.client.WorkflowOptions;
import io.temporal.client.WorkflowStub;
import io.temporal.opentracing.OpenTracingClientInterceptor;
import io.temporal.opentracing.OpenTracingOptions;
import io.temporal.opentracing.OpenTracingSpanContextCodec;
import io.temporal.opentracing.OpenTracingWorkerInterceptor;
import io.temporal.samples.tracing.workflow.TracingActivitiesImpl;
import io.temporal.samples.tracing.workflow.TracingChildWorkflowImpl;
import io.temporal.samples.tracing.workflow.TracingWorkflow;
import io.temporal.samples.tracing.workflow.TracingWorkflowImpl;
import io.temporal.testing.TestWorkflowRule;
import io.temporal.worker.WorkerFactoryOptions;
import java.util.List;
import org.junit.After;
import org.junit.Rule;
import org.junit.Test;

public class TracingTest {
  private final InMemoryReporter reporter = new InMemoryReporter();
  private final Sampler sampler = new ConstSampler(true);
  private final Tracer tracer =
      new JaegerTracer.Builder("temporal-test").withReporter(reporter).withSampler(sampler).build();

  private final OpenTracingOptions JAEGER_COMPATIBLE_CONFIG =
      OpenTracingOptions.newBuilder()
          .setSpanContextCodec(OpenTracingSpanContextCodec.TEXT_MAP_CODEC)
          .setTracer(tracer)
          .build();

  @Rule
  public TestWorkflowRule testWorkflowRule =
      TestWorkflowRule.newBuilder()
          .setWorkflowClientOptions(
              WorkflowClientOptions.newBuilder()
                  .setInterceptors(new OpenTracingClientInterceptor(JAEGER_COMPATIBLE_CONFIG))
                  .validateAndBuildWithDefaults())
          .setWorkerFactoryOptions(
              WorkerFactoryOptions.newBuilder()
                  .setWorkerInterceptors(new OpenTracingWorkerInterceptor(JAEGER_COMPATIBLE_CONFIG))
                  .validateAndBuildWithDefaults())
          .setWorkflowTypes(TracingWorkflowImpl.class, TracingChildWorkflowImpl.class)
          .setActivityImplementations(new TracingActivitiesImpl())
          .build();

  @After
  public void tearDown() {
    reporter.close();
    sampler.close();
    tracer.close();
  }

  @Test
  public void testReportSpans() {
    WorkflowClient client = testWorkflowRule.getWorkflowClient();
    WorkflowOptions workflowOptions =
        WorkflowOptions.newBuilder().setTaskQueue(testWorkflowRule.getTaskQueue()).build();
    TracingWorkflow workflow = client.newWorkflowStub(TracingWorkflow.class, workflowOptions);

    // Convert to untyped and start it with signalWithStart
    WorkflowStub untyped = WorkflowStub.fromTyped(workflow);
    untyped.signalWithStart("setLanguage", new Object[] {"Spanish"}, new Object[] {"John"});

    String greeting = untyped.getResult(String.class);
    assertEquals("Hola John", greeting);

    List<JaegerSpan> reportedSpans = reporter.getSpans();
    assertNotNull(reportedSpans);
    assertEquals(7, reportedSpans.size());
  }
}

package io.temporal.samples.retryonsignalinterceptor;

import static org.junit.Assert.*;

import io.temporal.api.common.v1.WorkflowExecution;
import io.temporal.client.WorkflowClient;
import io.temporal.client.WorkflowStub;
import io.temporal.failure.ActivityFailure;
import io.temporal.failure.ApplicationFailure;
import io.temporal.testing.TestWorkflowEnvironment;
import io.temporal.testing.TestWorkflowRule;
import io.temporal.worker.WorkerFactoryOptions;
import java.time.Duration;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.Rule;
import org.junit.Test;

public class RetryOnSignalInterceptorTest {

  static class TestActivityImpl implements MyActivity {

    final AtomicInteger count = new AtomicInteger();

    @Override
    public void execute() {
      if (count.incrementAndGet() < 5) {
        throw ApplicationFailure.newFailure("simulated", "type1");
      }
    }
  }

  private final TestActivityImpl testActivity = new TestActivityImpl();

  @Rule
  public TestWorkflowRule testWorkflowRule =
      TestWorkflowRule.newBuilder()
          .setWorkerFactoryOptions(
              WorkerFactoryOptions.newBuilder()
                  .setWorkerInterceptors(new RetryOnSignalWorkerInterceptor())
                  .validateAndBuildWithDefaults())
          .setWorkflowTypes(MyWorkflowImpl.class)
          .setActivityImplementations(testActivity)
          .build();

  @Test
  public void testRetryThenFail() {
    testActivity.count.set(0);
    TestWorkflowEnvironment testEnvironment = testWorkflowRule.getTestEnvironment();
    MyWorkflow workflow = testWorkflowRule.newWorkflowStub(MyWorkflow.class);
    WorkflowExecution execution = WorkflowClient.start(workflow::execute);

    // Get stub to the dynamically registered interface
    RetryOnSignalInterceptorListener listener =
        testWorkflowRule
            .getWorkflowClient()
            .newWorkflowStub(RetryOnSignalInterceptorListener.class, execution.getWorkflowId());
    testEnvironment.sleep(Duration.ofMinutes(10));
    listener.retry();
    testEnvironment.sleep(Duration.ofMinutes(10));
    listener.retry();
    testEnvironment.sleep(Duration.ofMinutes(10));
    listener.retry();
    testEnvironment.sleep(Duration.ofMinutes(10));
    listener.fail();
    WorkflowStub untyped =
        testWorkflowRule.getWorkflowClient().newUntypedWorkflowStub(execution.getWorkflowId());
    try {
      untyped.getResult(Void.class);
      fail("unreachable");
    } catch (Exception e) {
      assertTrue(e.getCause() instanceof ActivityFailure);
      assertTrue(e.getCause().getCause() instanceof ApplicationFailure);
      assertEquals(
          "message='simulated', type='type1', nonRetryable=false",
          e.getCause().getCause().getMessage());
    }
    assertEquals(4, testActivity.count.get());
  }

  @Test
  public void testRetryUntilSucceeds() {
    testActivity.count.set(0);
    TestWorkflowEnvironment testEnvironment = testWorkflowRule.getTestEnvironment();
    MyWorkflow workflow = testWorkflowRule.newWorkflowStub(MyWorkflow.class);
    WorkflowExecution execution = WorkflowClient.start(workflow::execute);

    // Get stub to the dynamically registered interface
    RetryOnSignalInterceptorListener listener =
        testWorkflowRule
            .getWorkflowClient()
            .newWorkflowStub(RetryOnSignalInterceptorListener.class, execution.getWorkflowId());
    for (int i = 0; i < 4; i++) {
      testEnvironment.sleep(Duration.ofMinutes(10));
      listener.retry();
    }
    WorkflowStub untyped =
        testWorkflowRule.getWorkflowClient().newUntypedWorkflowStub(execution.getWorkflowId());
    untyped.getResult(Void.class);
    assertEquals(5, testActivity.count.get());
  }
}

